class Solution {
  public int minOperations(int[] nums) {
    int[] stack = new int[nums.length];
    int top = 0, ops = 0;
    for (int x : nums) {
      if (x == 0) {
        top = 0;
        continue;
      }
      while (top > 0 && stack[top - 1] > x) top--;
      if (top == 0 || stack[top - 1] < x) {
        stack[top++] = x;
        ops++;
      }
    }
    return ops;
  }
}
